// TestQaItemStateRoundtrip — collections-ux 4.1, the Tier-1 joint: the FULL
// route→ledger→backfill loop over real instances, no mocks between modules —
// the real router+handler over real HTTP (httptest.Server), the real store
// ledger/progress/weight transactions, the real module registry behind the
// learning sweep's tag resolution. cmd/mellifera is package main and cannot
// be imported, so its thin-shell snippet on this loop is mirrored here in
// miniature (the qaRecsWatchDetect/qaRecsSweep precedent): the boot backfill
// (newRecsBackfill's body — ListWatched done-set → ListProgressAll stock
// scan → per-row floor decision against the STORED ffprobe duration →
// InsertWatched with the progress write's own stamp). Every module boundary
// that snippet JOINs is the production code under test. The learning loop
// rides this package's recs-roundtrip mirrors VERBATIM (qaRecsSweep +
// qaRecsResolveWatchTags, and qaRecsProbeDuration/qaRecsSeriesPath for the
// two document reads) — same real store, real registry.
//
// What ONLY a joint can prove (the 1.2 wire tests, internal/api/
// item_state_test.go, prove the endpoint's row-level contracts; the backfill
// probes, cmd/mellifera/recs_backfill_test.go, prove the decision in
// isolation): the loop's INTERACTION facts — a route-written watch keeps its
// position AND lands in the learning queue carrying the document-derived
// series anchor; an unwatch's zeroed position makes the item INVISIBLE to
// the boot backfill's positive-positions-only stock read even as the same
// pass backfills an above-floor peer (the positive control that keeps the
// negative assertion from passing vacuously); a re-watch after unwatch
// inserts a FRESH row (its completed_at stamp postdates the unwatch moment —
// a row that survived the unwatch would carry the first watch's stamp) and
// the learning pass consumes it exactly once, a second pass applying nothing
// new; and the photo/unknown-state 400s hold mid-loop with the ledger state
// intact. The fixtures carry no metadata namespaces, so the sweep's
// honest-absence path stamps without minting weight rows (the ApplyTagWeights
// contract); genre-flow-through-enrich-into-weights is the recs roundtrip's
// ground, referenced not re-proven.
package itest

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/api"
	"github.com/mellifera/mellifera/internal/module"
	"github.com/mellifera/mellifera/internal/scan"
	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/internal/web"
)

// qaStateJoint is one composed item-state round-trip world: the real store +
// module registry + the real api/web handler over real HTTP.
type qaStateJoint struct {
	baseURL string
	client  *http.Client
	token   string
	st      *store.Store
	reg     *module.Registry
}

// qaStateStartJoint composes the joint (the qa3Handler posture over a real
// listener): putItemState touches ONLY the store (GetItem, InsertWatched,
// DeleteWatched, GetProgress), so the api Deps carry the real store and a
// scan closure this loop never invokes; OnProgress stays nil — the detector
// leg is out of this joint's scope (its behavior is the recs roundtrip's
// ground, and nil is the documented silent no-op).
func qaStateStartJoint(t *testing.T) *qaStateJoint {
	t.Helper()
	ctx := context.Background()
	st, err := store.Open(ctx, filepath.Join(t.TempDir(), "qa-state.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	reg, err := module.Open(ctx, st)
	if err != nil {
		t.Fatalf("module.Open: %v", err)
	}
	token := "qa-state-admin-token"
	apiH := api.New(api.Deps{
		AdminToken: token,
		Store:      st,
		Scan:       func(context.Context, int64) (scan.Result, error) { return scan.Result{}, nil },
	})
	srv := httptest.NewServer(web.Handler(apiH, web.Options{}))
	t.Cleanup(srv.Close)
	return &qaStateJoint{
		baseURL: srv.URL,
		client:  &http.Client{Timeout: 30 * time.Second},
		token:   token,
		st:      st,
		reg:     reg,
	}
}

// qaStateSeedEpisode mirrors the scan path's PutItem (the element_hermetic_
// e2e scanPut idiom): the deterministic composite id and a fresh-scan
// document — parsed carrying the series anchor the watched branch reads
// (seriesPathOf), ffprobe carrying the stored duration the backfill's floor
// decision reads (the verbatim string-seconds emission). The 60 s duration
// puts the completion floor at 54 s (qaRecsFloor, the watchedDurationFloor
// mirror).
func qaStateSeedEpisode(t *testing.T, st *store.Store, libID int64, fileID, seriesDir string) string {
	t.Helper()
	ctx := context.Background()
	id := fmt.Sprintf("itm_%d_%s", libID, fileID)
	relPath := seriesDir + "/S01E01.mkv"
	doc, err := json.Marshal(map[string]any{
		"file_id":        fileID,
		"module_type":    "tv",
		"schema_version": 1,
		"parsed": map[string]any{
			"relative_path":        relPath,
			"stem":                 "S01E01",
			"series_relative_path": seriesDir,
		},
		"ffprobe": map[string]any{
			"format": map[string]any{"duration": "60"},
		},
	})
	if err != nil {
		t.Fatalf("marshal doc %s: %v", id, err)
	}
	if err := st.PutItem(ctx, store.Item{
		ID: id, ModuleID: "tv", LibraryID: libID, FileID: fileID,
		RelativePath: relPath, MediaType: "video",
		Document: doc, Status: "pending", SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("PutItem %s: %v", id, err)
	}
	return id
}

// qaStatePutState drives one PUT /items/{id}/state through the real route
// and decodes the echo into a raw map (the qa_endpoints key-level posture:
// completed_at's ABSENCE on an unwatched echo is a wire fact a struct decode
// cannot see).
func qaStatePutState(t *testing.T, j *qaStateJoint, itemID, state string) (int, map[string]any) {
	t.Helper()
	var dto map[string]any
	status := doRequest(t, j.client, http.MethodPut,
		j.baseURL+"/api/v1/items/"+itemID+"/state", j.token,
		map[string]any{"state": state}, &dto)
	return status, dto
}

// qaStatePutProgress writes one position through the real progress route
// (the write whose stored row the state loop reads back).
func qaStatePutProgress(t *testing.T, j *qaStateJoint, itemID string, position int64) {
	t.Helper()
	status := doRequest(t, j.client, http.MethodPut,
		j.baseURL+"/api/v1/progress/"+itemID, j.token,
		map[string]any{"position_seconds": position}, nil)
	if status != http.StatusOK {
		t.Fatalf("PUT progress %s: HTTP %d, want 200", itemID, status)
	}
}

// qaStateRunBackfill mirrors cmd/mellifera's newRecsBackfill body over the
// real store (package main cannot be imported — the qaRecsWatchDetect
// precedent): the ListWatched done-set, the ListProgressAll stock scan, the
// per-row floor decision against the STORED ffprobe duration (no stored
// duration ⇒ never backfills — the honest absence), and the InsertWatched
// carrying the progress write's own stamp (backfillStamp). Every failure is
// skip-and-continue exactly like production: the backfill is never
// load-bearing. The reads ride access.System() (the boot pass stays global —
// the l6-accounts law) and the write stamps the legacy slot, correct for
// this helper's slot-0 rows; production's per-row viewer shaping is pinned
// by cmd's own backfill tests.
func qaStateRunBackfill(ctx context.Context, t *testing.T, st *store.Store) {
	t.Helper()
	ledgered, err := st.ListWatched(ctx, access.System())
	if err != nil {
		t.Fatalf("backfill ListWatched: %v", err)
	}
	done := make(map[string]struct{}, len(ledgered))
	for _, id := range ledgered {
		done[id] = struct{}{}
	}
	rows, err := st.ListProgressAll(ctx, access.System())
	if err != nil {
		t.Fatalf("backfill ListProgressAll: %v", err)
	}
	for _, p := range rows {
		if _, ok := done[p.ItemID]; ok {
			continue // already in the ledger — the PK dedupe stays upstream
		}
		it, err := st.GetItem(ctx, p.ItemID, access.System())
		if err != nil {
			continue // vanished row — the tolerant reads already skip it
		}
		var doc map[string]any
		if err := json.Unmarshal(it.Document, &doc); err != nil {
			continue // stored document unreadable — log-and-skip
		}
		dur, ok := qaRecsProbeDuration(doc["ffprobe"])
		if !ok {
			continue // no stored duration — the documented honest absence
		}
		if float64(p.PositionSeconds) < qaRecsFloor*dur {
			continue // still mid-watch — the resume bonus is CORRECT here
		}
		stamp := time.Now().UTC()
		if ts, err := time.Parse(time.RFC3339Nano, p.UpdatedAt); err == nil {
			stamp = ts // backfillStamp: the progress write's own stamp
		}
		if err := st.InsertWatched(ctx, p.ItemID, it.LibraryID, qaRecsSeriesPath(doc), stamp, access.System()); err != nil {
			continue // log-and-skip — never load-bearing
		}
	}
}

// qaStateDecodeError decodes the api error body ({"error": {code, message,
// retryable}}) far enough to assert code + retryability.
func qaStateDecodeError(t *testing.T, dto map[string]any) (string, bool) {
	t.Helper()
	errObj, ok := dto["error"].(map[string]any)
	if !ok {
		t.Fatalf("error body %+v carries no error object", dto)
	}
	code, _ := errObj["code"].(string)
	retryable, _ := errObj["retryable"].(bool)
	return code, retryable
}

// TestQaItemStateRoundtrip is the collections-ux 4.1 joint: the watched
// toggle's full route→ledger→backfill loop. The subtests build on each
// other DELIBERATELY — the loop's facts are interaction facts, and the
// state carried between them IS the scenario (the TestRecsRoundtrip
// sequencing posture).
func TestQaItemStateRoundtrip(t *testing.T) {
	j := qaStateStartJoint(t)
	ctx := context.Background()

	lib, err := j.st.CreateLibrary(ctx, "tv", t.TempDir(), "QA State TV")
	if err != nil {
		t.Fatalf("CreateLibrary tv: %v", err)
	}
	itemA := qaStateSeedEpisode(t, j.st, lib, "file-a", "Show A")
	// itemB is the backfill leg's positive control, seeded inside its subtest
	// but read by the later ones (the loop's state carries — that IS the
	// scenario).
	var itemB string

	t.Run("watched write ledgers with position untouched", func(t *testing.T) {
		qaStatePutProgress(t, j, itemA, 42) // a mid-media position, via the real progress route

		status, dto := qaStatePutState(t, j, itemA, "watched")
		if status != http.StatusOK {
			t.Fatalf("PUT state watched: HTTP %d, want 200 (body %v)", status, dto)
		}
		if dto["item_id"] != itemA || dto["state"] != "watched" {
			t.Fatalf("echo = %v, want item_id %s watched", dto, itemA)
		}
		if pos, _ := dto["position_seconds"].(float64); pos != 42 {
			t.Fatalf("echo position_seconds = %v, want 42 (the watched write does NOT touch the position)", dto["position_seconds"])
		}
		completedAt, _ := dto["completed_at"].(string)
		if completedAt == "" {
			t.Fatalf("completed_at must be present on a watched echo: %v", dto)
		}
		if _, err := time.Parse(time.RFC3339Nano, completedAt); err != nil {
			t.Fatalf("completed_at %q is not RFC3339Nano: %v", completedAt, err)
		}

		watched, err := j.st.ListWatched(ctx, access.System())
		if err != nil {
			t.Fatalf("ListWatched: %v", err)
		}
		if len(watched) != 1 || watched[0] != itemA {
			t.Fatalf("watched ledger = %v, want exactly [%s]", watched, itemA)
		}
		rec, err := j.st.GetProgress(ctx, itemA, access.System())
		if err != nil || rec.PositionSeconds != 42 {
			t.Fatalf("GetProgress = (%+v, %v), want position 42 untouched", rec, err)
		}

		// The route write queued learning exactly like the detector path —
		// and the queue row carries the anchor read off the STORED document
		// (seriesPathOf at the joint, not the "" the wire tests seed).
		ids, libIDs, paths, _, err := j.st.ListUnappliedWatched(ctx)
		if err != nil {
			t.Fatalf("ListUnappliedWatched: %v", err)
		}
		if len(ids) != 1 || ids[0] != itemA {
			t.Fatalf("learning queue ids = %v, want [%s]", ids, itemA)
		}
		if len(libIDs) != 1 || libIDs[0] != lib || len(paths) != 1 || paths[0] != "Show A" {
			t.Fatalf("learning queue row = (lib %v, series %v), want (%d, Show A) — the document-derived anchor",
				libIDs, paths, lib)
		}
	})

	// The unwatch moment: the fresh-row assertion in the re-watch subtest
	// pivots on it — a row that SURVIVED the unwatch would carry the first
	// watch's stamp, which predates this line.
	unwatchAt := time.Now().UTC()

	t.Run("unwatched deletes the row and zeroes the position", func(t *testing.T) {
		status, dto := qaStatePutState(t, j, itemA, "unwatched")
		if status != http.StatusOK {
			t.Fatalf("PUT state unwatched: HTTP %d, want 200 (body %v)", status, dto)
		}
		if dto["state"] != "unwatched" {
			t.Fatalf("echo = %v, want unwatched", dto)
		}
		if pos, _ := dto["position_seconds"].(float64); pos != 0 {
			t.Fatalf("echo position_seconds = %v, want 0 (the one-tx reset)", dto["position_seconds"])
		}
		if _, present := dto["completed_at"]; present {
			t.Fatalf("completed_at = %v, want the KEY ABSENT on an unwatched echo (omitempty is the shape)", dto["completed_at"])
		}

		watched, err := j.st.ListWatched(ctx, access.System())
		if err != nil {
			t.Fatalf("ListWatched: %v", err)
		}
		if len(watched) != 0 {
			t.Fatalf("watched ledger = %v, want empty (the row is gone)", watched)
		}
		rec, err := j.st.GetProgress(ctx, itemA, access.System())
		if err != nil || rec.PositionSeconds != 0 {
			t.Fatalf("GetProgress = (%+v, %v), want position reset to 0", rec, err)
		}
	})

	t.Run("boot backfill does not re-ledger the unwatched item", func(t *testing.T) {
		// The positive control: above-floor stock with NO ledger row — what
		// the backfill exists to reconcile. 55 ≥ 0.9×60, the floor
		// predicate's satisfied side.
		itemB = qaStateSeedEpisode(t, j.st, lib, "file-b", "Show B")
		qaStatePutProgress(t, j, itemB, 55)

		// The stock read the boot pass runs: A is INVISIBLE — the unwatch's
		// zeroed position falls out of the positive-positions-only WHERE.
		// This read is the load-bearing fact; the pass below only proves the
		// negative holds through it.
		rows, err := j.st.ListProgressAll(ctx, access.System())
		if err != nil {
			t.Fatalf("ListProgressAll: %v", err)
		}
		if len(rows) != 1 || rows[0].ItemID != itemB || rows[0].PositionSeconds != 55 {
			t.Fatalf("backfill stock = %+v, want exactly [%s @55] — the unwatched item must be absent (position zeroed)", rows, itemB)
		}

		qaStateRunBackfill(ctx, t, j.st)

		// The pass provably RAN (B backfilled) yet did NOT re-ledger A —
		// the negative assertion holds non-vacuously.
		watched, err := j.st.ListWatched(ctx, access.System())
		if err != nil {
			t.Fatalf("ListWatched: %v", err)
		}
		if len(watched) != 1 || watched[0] != itemB {
			t.Fatalf("watched ledger after boot pass = %v, want exactly [%s] (peer backfilled, unwatched item NOT re-ledgered)", watched, itemB)
		}
	})

	t.Run("completion after unwatch inserts a fresh row and learns exactly once", func(t *testing.T) {
		status, dto := qaStatePutState(t, j, itemA, "watched")
		if status != http.StatusOK {
			t.Fatalf("PUT state watched (re-watch): HTTP %d, want 200 (body %v)", status, dto)
		}
		if dto["state"] != "watched" {
			t.Fatalf("echo = %v, want watched", dto)
		}
		// The post-write read sees the row the unwatch zeroed — the watched
		// write still does not touch the position.
		if pos, _ := dto["position_seconds"].(float64); pos != 0 {
			t.Fatalf("echo position_seconds = %v, want 0 (the zeroed row, untouched by the ledger write)", dto["position_seconds"])
		}

		watched, err := j.st.ListWatched(ctx, access.System())
		if err != nil {
			t.Fatalf("ListWatched: %v", err)
		}
		if len(watched) != 2 {
			t.Fatalf("watched ledger = %v, want exactly {%s, %s}", watched, itemA, itemB)
		}

		// BOTH completions queue learning: A's route-written row AND B's
		// backfilled row (in production the backfill pokes the same recs
		// wake). A's row is FRESH: its completed_at stamp postdates the
		// unwatch moment — a row that had survived the unwatch would carry
		// the first watch's stamp and fail this comparison.
		ids, _, _, completed, err := j.st.ListUnappliedWatched(ctx)
		if err != nil {
			t.Fatalf("ListUnappliedWatched: %v", err)
		}
		if len(ids) != 2 {
			t.Fatalf("learning queue = %v, want exactly {%s, %s}", ids, itemA, itemB)
		}
		aStamp := time.Time{}
		for i, id := range ids {
			if id == itemA {
				aStamp = completed[i]
			}
		}
		if aStamp.IsZero() {
			t.Fatalf("learning queue %v carries no %s row", ids, itemA)
		}
		if !aStamp.After(unwatchAt) {
			t.Fatalf("%s row stamp %v does not postdate the unwatch (%v) — the insert was NOT fresh (the PK kept a pre-unwatch row)", itemA, aStamp, unwatchAt)
		}

		// The learning pass (the recs joint's mirror, reused verbatim over
		// the same real store + registry) consumes the queue: one pass, all
		// rows stamped, no weight rows minted (the fixtures resolve no tags
		// — the honest-absence path stamps without touching a weight).
		qaRecsSweep(ctx, j.st, j.reg)
		if ids, _, _, _, err := j.st.ListUnappliedWatched(ctx); err != nil || len(ids) != 0 {
			t.Fatalf("learning queue after the apply pass = (%v, err %v), want empty (every row stamped)", ids, err)
		}
		if got := qaRecsReadWeights(t, j.st); len(got) != 0 {
			t.Fatalf("weights after the apply pass = %v, want empty (honest absence: no tags resolved, no weight rows minted)", got)
		}

		// The second pass applies nothing new — "exactly once".
		qaRecsSweep(ctx, j.st, j.reg)
		if ids, _, _, _, err := j.st.ListUnappliedWatched(ctx); err != nil || len(ids) != 0 {
			t.Fatalf("learning queue after the second pass = (%v, err %v), want still empty", ids, err)
		}
		if got := qaRecsReadWeights(t, j.st); len(got) != 0 {
			t.Fatalf("weights after the second pass = %v, want unchanged empty (nothing new applied)", got)
		}
	})

	t.Run("photo and unknown state rejections hold mid-loop", func(t *testing.T) {
		photoLib, err := j.st.CreateLibrary(ctx, "image", t.TempDir(), "QA State Photos")
		if err != nil {
			t.Fatalf("CreateLibrary image: %v", err)
		}
		photoID := fmt.Sprintf("itm_%d_photo", photoLib)
		if err := j.st.PutItem(ctx, store.Item{
			ID: photoID, ModuleID: "image", LibraryID: photoLib, FileID: "photo",
			RelativePath: "p.jpg", MediaType: "image",
			Document: json.RawMessage(`{}`), SchemaVersion: 1,
		}); err != nil {
			t.Fatalf("PutItem photo: %v", err)
		}

		for _, tc := range []struct {
			name  string
			item  string
			state string
		}{
			{"photo_module_item", photoID, "watched"},
			{"unknown_state", itemA, "archived"},
		} {
			t.Run(tc.name, func(t *testing.T) {
				status, dto := qaStatePutState(t, j, tc.item, tc.state)
				if status != http.StatusBadRequest {
					t.Fatalf("PUT state %q on %s: HTTP %d, want 400", tc.state, tc.item, status)
				}
				code, retryable := qaStateDecodeError(t, dto)
				if code != "bad_request" || retryable {
					t.Fatalf("error body = %v, want bad_request/non-retryable", dto)
				}
			})
		}

		// Neither rejection touched the settled loop state: the ledger holds
		// its two rows, the queue stays empty, A's position stays 0.
		watched, err := j.st.ListWatched(ctx, access.System())
		if err != nil {
			t.Fatalf("ListWatched: %v", err)
		}
		if len(watched) != 2 {
			t.Fatalf("watched ledger after the rejections = %v, want {%s, %s} untouched", watched, itemA, itemB)
		}
		if ids, _, _, _, err := j.st.ListUnappliedWatched(ctx); err != nil || len(ids) != 0 {
			t.Fatalf("learning queue after the rejections = (%v, err %v), want empty (rejections queue nothing)", ids, err)
		}
		rec, err := j.st.GetProgress(ctx, itemA, access.System())
		if err != nil || rec.PositionSeconds != 0 {
			t.Fatalf("GetProgress %s after the rejections = (%+v, %v), want position 0 untouched", itemA, rec, err)
		}
	})
}
